gsap.registerPlugin(SplitText, ScrollTrigger);

/* ============================================
   INIT ALL ELEMENTS WITH data-text-block
============================================ */

document.querySelectorAll('[data-text-block]').forEach((el) => {
  /* ============================================
     GET DATA ATTRIBUTES
  ============================================ */

  const mode = el.dataset.mode || 'words';
  const color = el.dataset.color || '#00ffa6';
  const delay = parseFloat(el.dataset.delay) || 0;
  const stagger = parseFloat(el.dataset.stagger) || 0.05;
  const moveX = parseFloat(el.dataset.x) || 0;
  const moveY = parseFloat(el.dataset.y) || 0;

  /* ============================================
     SPLIT TEXT
  ============================================ */

  const split = new SplitText(el, {
    type: mode,
    linesClass: 'line',
    wordsClass: 'word',
    charsClass: 'char',
  });

  /* ============================================
     SELECT TARGETS
  ============================================ */

  let targets;
  let maskClass;

  if (mode === 'lines') {
    targets = split.lines;
    maskClass = 'line-mask';
  }

  if (mode === 'words') {
    targets = split.words;
    maskClass = 'word-mask';
  }

  if (mode === 'chars') {
    targets = split.chars;
    maskClass = 'char-mask';
  }

  /* ============================================
     CREATE MASK
  ============================================ */

  targets.forEach((item) => {
    const mask = document.createElement('div');

    mask.classList.add(maskClass);

    mask.style.background = color;

    item.appendChild(mask);
  });

  /* ============================================
     MASK SHRINK ANIMATION
  ============================================ */

  const masks = el.querySelectorAll(`.${maskClass}`);

  gsap.to(masks, {
    scaleX: 0,

    duration: 1,

    delay: delay,

    stagger: stagger,

    ease: 'power4.inOut',

    scrollTrigger: {
      trigger: el,
      start: 'top 85%',
    },
  });

  /* ============================================
     TEXT ANIMATION
  ============================================ */

  gsap.from(targets, {
    x: moveX,

    y: moveY,

    opacity: 0,

    duration: 1,

    delay: delay,

    stagger: stagger,

    ease: 'power3.out',

    scrollTrigger: {
      trigger: el,
      start: 'top 85%',
    },
  });
});